#!/usr/bin/env python3
"""
rasterize_pages.py — render PDF pages to PNGs for Gemini vision OCR, using
`pdftoppm -r 250` (the DPI proven out in ocr_toc_gemini.py, generalized from
ToC-only pages to arbitrary page lists).

Cleanup discipline (this was a flaw in the old ocr_toc_gemini.py workflow,
which left rasterized PNGs sitting in /tmp indefinitely):
  - Every invocation creates its OWN fresh subdirectory under
    tempfile.mkdtemp(prefix='gemini_ocr_'), never a fixed/shared path.
  - The CALLER (gemini_ocr.ts) is responsible for deleting that directory
    once it has read + base64-encoded the PNGs into the Gemini request —
    this script's job is only to produce the files and report their paths;
    it does not delete on success (the caller needs the files to still
    exist when this process exits).
  - On any FAILURE during rasterization, this script DOES clean up its own
    temp dir before exiting non-zero, so a crash mid-run doesn't litter
    /tmp with partial output either.

Usage:
  python3 rasterize_pages.py <path/to/file.pdf> --pages "5,7,9-12" [--dpi 250]

Output (stdout, JSON on success):
  {
    "temp_dir": "/tmp/gemini_ocr_xxxxxxxx",
    "dpi": 250,
    "pages": [
      {"page_number": 5, "png_path": "/tmp/gemini_ocr_xxxxxxxx/page-05.png"},
      ...
    ]
  }

On error: prints {"error": "<actionable message>"} to stdout, exits 1, and
removes any temp dir it created.
"""

import argparse
import json
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

DEFAULT_DPI = 250


def parse_page_spec(spec: str) -> list[int]:
    pages: set[int] = set()
    for part in spec.split(","):
        part = part.strip()
        if not part:
            continue
        if "-" in part:
            start_s, end_s = part.split("-", 1)
            start, end = int(start_s), int(end_s)
            if start < 1 or end < start:
                raise ValueError(f'malformed page range segment "{part}"')
            pages.update(range(start, end + 1))
        else:
            p = int(part)
            if p < 1:
                raise ValueError(f"page {p} must be >= 1")
            pages.add(p)
    return sorted(pages)


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("document_path")
    ap.add_argument("--pages", required=True, help='e.g. "5,7,9-12"')
    ap.add_argument("--dpi", type=int, default=DEFAULT_DPI)
    args = ap.parse_args()

    doc_path = Path(args.document_path)
    if not doc_path.exists():
        print(
            json.dumps({"error": f"document_path does not exist: {args.document_path}"})
        )
        return 1

    if shutil.which("pdftoppm") is None:
        print(
            json.dumps(
                {
                    "error": (
                        "pdftoppm (poppler-utils) is not installed or not on PATH. "
                        "Install poppler (e.g. `brew install poppler`) before calling gemini_ocr "
                        "on scanned pages."
                    )
                }
            )
        )
        return 1

    try:
        page_numbers = parse_page_spec(args.pages)
    except ValueError as e:
        print(json.dumps({"error": f"invalid --pages value: {e}"}))
        return 1

    if not page_numbers:
        print(json.dumps({"error": f'--pages "{args.pages}" resolved to zero pages'}))
        return 1

    temp_dir = Path(tempfile.mkdtemp(prefix="gemini_ocr_"))
    try:
        results = []
        # pdftoppm renders a contiguous -f/-l range per invocation; since our
        # page list may have gaps (e.g. "5,7,9-12"), we call it once per
        # contiguous run of pages rather than once per page, to keep process
        # spawn overhead down while still only rendering requested pages.
        for run_start, run_end in _contiguous_runs(page_numbers):
            prefix = temp_dir / f"run-{run_start}-{run_end}"
            cmd = [
                "pdftoppm",
                "-png",
                "-r",
                str(args.dpi),
                "-f",
                str(run_start),
                "-l",
                str(run_end),
                str(doc_path),
                str(prefix),
            ]
            proc = subprocess.run(cmd, capture_output=True, text=True)
            if proc.returncode != 0:
                raise RuntimeError(
                    f"pdftoppm failed on pages {run_start}-{run_end}: {proc.stderr.strip()}"
                )
            for page_number in range(run_start, run_end + 1):
                # pdftoppm names outputs <prefix>-<N>.png with N zero-padded
                # to the width of the highest page number in the run.
                # pdftoppm pads its numeric suffix to at least 2 digits (its
                # own internal minimum), not simply len(str(run_end)) — a
                # single- or double-digit run_end (e.g. "1-2") still produces
                # "-01.png"/"-02.png", not "-1.png"/"-2.png". Try the range
                # of widths pdftoppm is actually known to use (2 up to the
                # digit count of run_end) before giving up.
                candidate = None
                for width in sorted({2, len(str(run_end))}):
                    probe = Path(f"{prefix}-{page_number:0{width}d}.png")
                    if probe.exists():
                        candidate = probe
                        break
                if candidate is None:
                    # single-page runs sometimes omit the numeric suffix
                    probe = Path(f"{prefix}.png")
                    if probe.exists():
                        candidate = probe
                if candidate is None:
                    raise RuntimeError(
                        f"expected rasterized output for page {page_number} not found "
                        f"(looked for {prefix}-{page_number:02d}.png)"
                    )
                results.append({"page_number": page_number, "png_path": str(candidate)})

        results.sort(key=lambda r: r["page_number"])
        print(
            json.dumps({"temp_dir": str(temp_dir), "dpi": args.dpi, "pages": results})
        )
        return 0
    except Exception as e:  # noqa: BLE001
        shutil.rmtree(temp_dir, ignore_errors=True)
        print(json.dumps({"error": f"rasterization failed: {e}"}))
        return 1


def _contiguous_runs(pages: list[int]) -> list[tuple[int, int]]:
    runs: list[tuple[int, int]] = []
    start = prev = pages[0]
    for p in pages[1:]:
        if p == prev + 1:
            prev = p
            continue
        runs.append((start, prev))
        start = prev = p
    runs.append((start, prev))
    return runs


if __name__ == "__main__":
    sys.exit(main())
